    #[test]
    fn trail_pack_catalog_refreshes_for_new_snapshot_and_replacement() {
        let synthwave_path = trail_pack_asset("synthwave.toml");
        let emberfall_path = trail_pack_asset("emberfall.toml");
        let synthwave_text =
            trail_pack_config(std::slice::from_ref(&synthwave_path), "pack:synthwave");
        let synthwave_config: Config = toml::from_str(&synthwave_text).unwrap();

        let direct = SettingsViewState::new(&synthwave_config);
        assert!(
            direct.legacy.trail_pack_ids.is_empty(),
            "compatibility constructor stays manifest-IO-free"
        );

        let mut service = VersionedConfigService::new(synthwave_text).unwrap();
        let service_snapshot = service.snapshot();
        let synthwave_fp = service_snapshot
            .assets
            .trail_packs
            .get("synthwave")
            .expect("loaded synthwave")
            .pack_fp;
        assert_ne!(synthwave_fp, 0);

        let mut snapshot = SettingsViewState::from_snapshot(&service_snapshot).unwrap();
        assert_eq!(snapshot.legacy.trail_pack_ids, ["synthwave"]);
        assert_eq!(
            snapshot
                .trail_pack_catalog()
                .get("synthwave")
                .map(|pack| pack.pack_fp),
            Some(synthwave_fp)
        );

        let replacement = service
            .replace_external(trail_pack_config(
                std::slice::from_ref(&emberfall_path),
                "pack:emberfall",
            ))
            .unwrap();
        snapshot.replace_snapshot(&replacement).unwrap();
        assert_eq!(snapshot.legacy.trail_pack_ids, ["emberfall"]);
        assert!(
            !snapshot
                .trail_pack_catalog()
                .packs
                .contains_key("synthwave")
        );
        assert!(
            snapshot
                .trail_pack_catalog()
                .packs
                .contains_key("emberfall")
        );
    }

    // The fallback raw projection (`SettingsViewState::new` — the recovery/test
    // path) must treat dotted keys exactly like the snapshot projection, at
    // BOTH registered depths: a configured `[matrix_rain]`/`[packages]` bool
    // and a configured `[sparkle_words.*]` sub-table bool are EXPLICIT
    // (present in the Modified review; OCC expects `Exact(Some(..))`), an
    // absent one is not.
    #[test]
    fn fallback_raw_projection_covers_dotted_keys() {
        let config: Config = toml::from_str(
            "[matrix_rain]\nenabled = true\n[packages]\nenabled = false\nauto_update = false\nauto_install = true\n\
             [sparkle_words.profanity]\nenabled = false\n[sparkle_words.feline]\nenabled = true\n\
             [sparkle_words.ink]\nloop = true\n",
        )
        .unwrap();
        let state = SettingsViewState::new(&config);
        for (key, want) in [
            (prefs::EDIT_MATRIX_RAIN_ENABLED, "true"),
            (prefs::EDIT_PACKAGES_ENABLED, "false"),
            (prefs::EDIT_PACKAGES_AUTO_UPDATE, "false"),
            (prefs::EDIT_PACKAGES_AUTO_INSTALL, "true"),
            ("sparkle_words.profanity.enabled", "false"),
            ("sparkle_words.feline.enabled", "true"),
            ("sparkle_words.ink.loop", "true"),
        ] {
            assert!(state.is_explicit(key), "{key} configured ⇒ explicit");
            assert_eq!(state.raw_value(key).as_deref(), Some(want), "{key}");
        }
        let absent = SettingsViewState::new(&Config::default());
        for key in [
            prefs::EDIT_MATRIX_RAIN_ENABLED,
            prefs::EDIT_PACKAGES_ENABLED,
            prefs::EDIT_PACKAGES_AUTO_UPDATE,
            prefs::EDIT_PACKAGES_AUTO_INSTALL,
            "sparkle_words.profanity.enabled",
            "sparkle_words.feline.enabled",
            "sparkle_words.ink.loop",
        ] {
            assert!(!absent.is_explicit(key), "{key} absent ⇒ not explicit");
        }
    }

    // The production snapshot path for a DEPTH-2 leaf: a hand-set
    // `sparkle_words.profanity.enabled` is explicit with its exact raw value
    // (the full-depth dotted projection, not the whole-table opaque entry),
    // and an absent one is not.
    #[test]
    fn snapshot_projection_covers_depth_two_dotted_keys() {
        let service =
            VersionedConfigService::new("[sparkle_words.profanity]\nenabled = false\n".into())
                .unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        assert!(state.is_explicit("sparkle_words.profanity.enabled"));
        assert_eq!(
            state
                .raw_value("sparkle_words.profanity.enabled")
                .as_deref(),
            Some("false")
        );
        let absent = VersionedConfigService::new(String::new()).unwrap();
        let absent = SettingsViewState::from_snapshot(&absent.snapshot()).unwrap();
        assert!(!absent.is_explicit("sparkle_words.profanity.enabled"));
    }

    #[test]
    fn native_trail_picker_has_dynamic_choices_and_human_labels() {
        let config = Config {
            cursor_trail_style: Some("pack:synthwave".to_string()),
            ..Config::default()
        };
        let state = SettingsViewState::new(&config);
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .expect("trail style field");
        let ids = vec!["synthwave".to_string(), "ember_fall".to_string()];
        let choices = choices_for_field(field, &ids, &state.assets.themes).expect("trail choices");
        assert_eq!(
            &choices[..prefs::CURSOR_TRAIL_STYLES.len()],
            prefs::CURSOR_TRAIL_STYLES
        );
        assert_eq!(
            &choices[prefs::CURSOR_TRAIL_STYLES.len()..],
            ["pack:ember_fall", "pack:synthwave"]
        );

        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices,
            "pack:synthwave",
            true,
            true,
            "phaser",
            &state.assets.themes,
        );
        assert_eq!(
            picker.options[picker.selected].value.as_deref(),
            Some("pack:synthwave")
        );
        assert_eq!(
            picker.options[picker.selected].label,
            "Trail Pack · Synthwave"
        );
        assert!(picker.options.iter().any(|option| {
            option.label == "Trail Pack · Ember fall"
                && option.value.as_deref() == Some("pack:ember_fall")
        }));
        assert_eq!(
            picker
                .options
                .iter()
                .filter(|option| option.value.as_deref() == Some("pack:synthwave"))
                .count(),
            1,
            "the configured pack appears exactly once"
        );
    }

    #[test]
    fn native_theme_picker_keeps_builtins_first_and_adds_user_themes_once() {
        let choices = merge_theme_options([
            "My Solarized".to_string(),
            "dracula".to_string(),
            "Work Light".to_string(),
        ]);
        let builtins = aterm_types::scheme::builtin_names();
        assert_eq!(
            &choices[..builtins.len()],
            builtins.as_slice(),
            "the stable built-in registry remains the first picker section"
        );
        assert_eq!(
            &choices[builtins.len()..],
            ["My Solarized", "Work Light"],
            "user themes append in discovery order and cannot duplicate a built-in"
        );

        let picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            ["Nord".to_string()],
            "Nord",
            true,
            true,
            "Default",
            &crate::app_config::ThemeCatalog::default(),
        );
        let nord = picker
            .options
            .iter()
            .find(|option| option.value.as_deref() == Some("Nord"))
            .expect("Nord picker option");
        assert_eq!(
            nord.terminal_theme,
            aterm_types::scheme::builtin("Nord")
                .as_ref()
                .map(PreviewTerminalTheme::from_scheme),
            "picker-open parsing caches the exact live preview palette"
        );

        let work_scheme = aterm_types::scheme::builtin("Dracula").unwrap();
        let custom = crate::app_config::ThemeCatalog::from_schemes([(
            "Work".to_string(),
            work_scheme.clone(),
        )]);
        assert!(settings_theme_options(&custom).ends_with(&["Work".to_string()]));
        let custom_picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            settings_theme_options(&custom),
            "work",
            true,
            true,
            "Default",
            &custom,
        );
        let work = custom_picker
            .options
            .iter()
            .find(|option| option.value.as_deref() == Some("Work"))
            .unwrap();
        assert_eq!(
            work.terminal_theme,
            Some(PreviewTerminalTheme::from_scheme(&work_scheme)),
            "picker and runtime share case-insensitive custom-theme identity without a second file read"
        );
    }

    #[test]
    fn choice_picker_page_resize_preserves_selected_or_intentionally_paged_window() {
        for selected in [6_usize, 7] {
            for target in [3_usize, 2, 1] {
                let values = (0..10).map(|index| format!("Choice {index}"));
                let current = format!("Choice {selected}");
                let picker = ChoicePicker::new(
                    prefs::EDIT_THEME,
                    values,
                    &current,
                    false,
                    true,
                    "Choice 0",
                    &crate::app_config::ThemeCatalog::default(),
                );
                picker.page_size.set(4);
                picker.offset.set(4);
                picker.configure_page_size(target);
                assert!(
                    picker.visible_range().contains(&selected),
                    "4→{target} must keep selected boundary {selected} visible"
                );
                assert_eq!(picker.offset.get(), (selected / target) * target);
            }
        }

        let picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            (0..10).map(|index| format!("Choice {index}")),
            "Choice 7",
            false,
            true,
            "Choice 0",
            &crate::app_config::ThemeCatalog::default(),
        );
        picker.page_size.set(4);
        picker.offset.set(0);
        picker.configure_page_size(3);
        assert_eq!(picker.offset.get(), 0);
        assert!(
            !picker.visible_range().contains(&picker.selected),
            "an intentionally paged-away selection must not pull the user's window"
        );

        picker.page_size.set(1);
        picker.offset.set(7);
        picker.configure_page_size(4);
        assert!(picker.visible_range().contains(&picker.selected));
        assert_eq!(
            picker.offset.get(),
            4,
            "1→4 expansion realigns around selection"
        );
    }

    #[test]
    fn split_theme_preview_follows_os_appearance_not_overridden_background_luminance() {
        let service = VersionedConfigService::new(
            "theme = \"dark:Dracula,light:GitHub Light\"\nbackground = \"#000000\"\n".to_string(),
        )
        .unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        let misleading_dark_host = aterm_render::Theme {
            bg: 0x000000,
            ..aterm_render::Theme::default()
        };
        let light = preview_terminal_theme(&state, misleading_dark_host, false);
        let dark = preview_terminal_theme(&state, misleading_dark_host, true);
        let expected_light = PreviewTerminalTheme::from_scheme(
            &aterm_types::scheme::builtin("GitHub Light").unwrap(),
        );
        let expected_dark =
            PreviewTerminalTheme::from_scheme(&aterm_types::scheme::builtin("Dracula").unwrap());

        assert_eq!(light.fg, expected_light.fg);
        assert_eq!(light.ansi, expected_light.ansi);
        assert_eq!(dark.fg, expected_dark.fg);
        assert_eq!(dark.ansi, expected_dark.ansi);
        assert_eq!(light.bg, 0x000000, "authored slot overrides still win");
        assert_eq!(dark.bg, 0x000000, "authored slot overrides still win");
    }

    #[test]
    fn theme_projection_and_preview_share_catalog_split_and_default_fallback_semantics() {
        let state_with_themes = |source: &str, themes: Arc<crate::app_config::ThemeCatalog>| {
            let config: Config = toml::from_str(source).unwrap();
            let mut assets = (*crate::app_config::ConfigAssetCatalog::empty()).clone();
            assets.themes = themes;
            SettingsViewState::from_config_and_assets(&config, Arc::new(assets))
        };
        let project = |state: &SettingsViewState| {
            setting_effect_projection(
                state,
                None,
                prefs::EDIT_THEME,
                audited_availability(),
                crate::native_app::ViewMotionCx::default(),
            )
        };
        let host = aterm_render::Theme {
            fg: 0x01_0203,
            bg: 0x04_0506,
            cursor: 0x07_0809,
            selection: 0x0A_0B0C,
        };
        let default = PreviewTerminalTheme::from_scheme(&aterm_types::ColorScheme::default());

        let builtin = state_with_themes(
            "theme = \"Nord\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&builtin, host, false),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Nord").expect("built-in Nord")
            )
        );
        assert!(!effect_note_contains(&project(&builtin), "unavailable"));

        let missing = state_with_themes(
            "theme = \"Office Missing\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(preview_terminal_theme(&missing, host, false), default);
        assert!(effect_note_contains(&project(&missing), "Default fallback"));

        let split_missing = state_with_themes(
            "theme = \"dark:Dracula,light:Office Missing\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&split_missing, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert_eq!(preview_terminal_theme(&split_missing, host, false), default);
        let split_note = project(&split_missing);
        assert!(effect_note_contains(
            &split_note,
            "light \"Office Missing\""
        ));
        assert!(effect_note_contains(&split_note, "Default fallback"));

        let omitted_light = state_with_themes(
            "theme = \"dark:Dracula\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(preview_terminal_theme(&omitted_light, host, false), default);
        assert_eq!(
            preview_terminal_theme(&omitted_light, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert!(
            project(&omitted_light).notes.is_empty(),
            "an intentionally omitted side is Default, not an unavailable theme"
        );

        let invalid_split = state_with_themes(
            "theme = \"dark:Dracula,night:Nord\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&invalid_split, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert_eq!(preview_terminal_theme(&invalid_split, host, false), default);
        let invalid_projection = project(&invalid_split);
        assert!(effect_note_contains(
            &invalid_projection,
            "Invalid theme selector"
        ));
        assert!(effect_note_contains(
            &invalid_projection,
            "Dark (Dracula) still applies"
        ));
        assert!(invalid_projection.has_live_effect);

        let work_scheme = aterm_types::scheme::builtin("GitHub Light").unwrap();
        let custom = state_with_themes(
            "theme = \"Work\"\n",
            crate::app_config::ThemeCatalog::from_schemes([(
                "Work".to_string(),
                work_scheme.clone(),
            )]),
        );
        assert_eq!(
            preview_terminal_theme(&custom, host, false),
            PreviewTerminalTheme::from_scheme(&work_scheme)
        );
        assert!(project(&custom).notes.is_empty());
    }

    #[test]
    fn highlighted_uncommitted_trail_pack_is_the_live_preview_candidate() {
        let synthwave_path = trail_pack_asset("synthwave.toml");
        let service = VersionedConfigService::new(trail_pack_config(
            std::slice::from_ref(&synthwave_path),
            "phaser",
        ))
        .unwrap();
        let mut state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        state.navigate(SettingsRoute::CursorMotion);
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();
        let before =
            renderer_preview_spec(&state, 900, motion, 13.0, theme).expect("committed preview");

        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .expect("trail style field");
        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
                .expect("trail choices"),
            SettingsState::display_value(field),
            state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE),
            field.seed.is_some(),
            &effective_default_for_field(prefs::EDIT_CURSOR_TRAIL_STYLE),
            &state.assets.themes,
        );
        let pack_index = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("pack:synthwave"))
            .expect("pack option");
        picker
            .offset
            .set((pack_index / ChoicePicker::PAGE_SIZE) * ChoicePicker::PAGE_SIZE);
        state.choice_picker = Some(picker);
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/choice/{}/{pack_index}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )));

        let candidate =
            renderer_preview_spec(&state, 900, motion, 13.0, theme).expect("candidate preview");
        assert_eq!(candidate.cursor.trail_style, PreviewTrailStyle::Custom);
        assert_eq!(
            candidate
                .cursor
                .trail_pack
                .as_ref()
                .map(|pack| pack.pack_fp),
            state
                .trail_pack_catalog()
                .get("synthwave")
                .map(|pack| pack.pack_fp)
        );
        assert_eq!(candidate.animation(), PreviewAnimation::Continuous);
        assert!(
            candidate
                .audit_value()
                .contains("Trail Pack interpreter is live")
        );
        assert_ne!(before.paint_fingerprint(), candidate.paint_fingerprint());
        assert_eq!(
            state.raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE).as_deref(),
            Some("phaser"),
            "moving picker focus previews without persisting"
        );
    }

    #[test]
    fn preview_activity_comes_from_the_exact_authored_spec() {
        let mut home = SettingsViewState::new(&Config::default());
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 1_200.0, 720.0),
            ),
            PreviewAnimation::Continuous,
            "wide Top Settings animates its visible cursor runway without requiring focus"
        );
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 390.0, 568.0),
            ),
            PreviewAnimation::None,
            "compact Top Settings page 0 renders only a static theme sample"
        );
        home.page_scroll = 2;
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 390.0, 568.0),
            ),
            PreviewAnimation::Continuous,
            "the visible cursor-trail slice keeps its live preview"
        );

        let mut appearance = SettingsViewState::new(&Config::default());
        appearance.navigate(SettingsRoute::Appearance);
        assert_eq!(
            appearance.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::None,
            "Appearance is a genuinely static renderer sample"
        );
        assert!(
            renderer_preview_spec(&appearance, 100, motion, 17.5, theme)
                .unwrap()
                .audit_value()
                .contains("17.5 px"),
            "an unset font-size preview uses the renderer's applied size"
        );
        assert!(
            renderer_preview_spec(&appearance, 100, motion, 1.0, theme)
                .unwrap()
                .audit_value()
                .contains("6 px"),
            "host font fallback is normalized to the prefs minimum"
        );

        for (authored, expected) in [
            ("BAR", PreviewCursorStyle::Bar),
            (" Beam ", PreviewCursorStyle::Bar),
            ("Underline", PreviewCursorStyle::Bar),
            ("hidden", PreviewCursorStyle::Block),
        ] {
            let config: Config = toml::from_str(&format!(
                "cursor_style = {authored:?}\ncursor_blink = false\ncursor_trail = false\n"
            ))
            .unwrap();
            let mut state = SettingsViewState::new(&config);
            state.navigate(SettingsRoute::CursorMotion);
            assert_eq!(
                renderer_preview_spec(&state, 100, motion, 13.0, theme)
                    .unwrap()
                    .cursor
                    .style,
                expected,
                "cursor preview must share the owning resolver for {authored:?}"
            );
        }

        let hidden: Config = toml::from_str(
            "cursor_style = \"hidden\"\ncursor_blink = true\ncursor_trail = false\n",
        )
        .unwrap();
        let mut hidden = SettingsViewState::new(&hidden);
        hidden.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            hidden.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::BlinkEdge { after_ms: 430 },
            "an unknown configured cursor style falls back to the runtime's blinking Block"
        );

        let blink: Config =
            toml::from_str("cursor_style = \"block\"\ncursor_blink = true\ncursor_trail = false\n")
                .unwrap();
        let mut blink = SettingsViewState::new(&blink);
        blink.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            blink.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::BlinkEdge { after_ms: 430 }
        );

        let zero: Config = toml::from_str(
            "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"phaser\"\ncursor_trail_intensity = 0.0\n",
        )
        .unwrap();
        let mut zero = SettingsViewState::new(&zero);
        zero.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            zero.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::None,
            "a zero-intensity trail does not arm invisible work"
        );
    }

    #[test]
    fn canonical_non_cursor_previews_are_pixel_static_across_live_blink_edges() {
        crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
        let config: Config = toml::from_str(
            "cursor_style = \"bar\"\ncursor_blink = true\ncursor_trail = true\ncursor_trail_style = \"phaser\"\n",
        )
        .unwrap();
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();

        for route in [
            SettingsRoute::Appearance,
            SettingsRoute::TextFonts,
            SettingsRoute::WindowTabs,
        ] {
            let mut state = SettingsViewState::new(&config);
            state.navigate(route);
            let early = renderer_preview_spec(&state, 100, motion, 13.0, theme)
                .unwrap_or_else(|| panic!("early {route:?} preview"));
            let late = renderer_preview_spec(&state, 600, motion, 13.0, theme)
                .unwrap_or_else(|| panic!("late {route:?} preview"));

            assert_eq!(early.animation(), PreviewAnimation::None, "{route:?}");
            assert_eq!(late.animation(), PreviewAnimation::None, "{route:?}");
            assert!(!early.cursor.blink, "{route:?} keeps its static cursor");
            assert!(
                !early.cursor.trail_enabled,
                "{route:?} keeps cursor motion out of its scene"
            );
            assert_eq!(
                early.paint_fingerprint(),
                late.paint_fingerprint(),
                "{route:?} retained identity is phase-static"
            );
            assert_eq!(
                compile_preview_for_pixels(early).1,
                compile_preview_for_pixels(late).1,
                "{route:?} pixels are phase-static"
            );
        }
    }

    #[test]
    fn serious_mode_suppresses_native_preview_trails_post_fx_and_cadence() {
        let config: Config = toml::from_str(
            "cursor_blink = true\n\
             cursor_trail = true\n\
             cursor_trail_style = \"fire\"\n\
             cursor_trail_bloom = true\n\
             cursor_fire_shimmer = true\n\
             hdr_glow = true\n\
             cursor_glow_sdr_boost = 0.5\n",
        )
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_CURSOR_FIRE_SHIMMER
        )));
        let theme = aterm_render::Theme::default();

        let active = renderer_preview_spec(
            &state,
            100,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            theme,
        )
        .expect("active cursor preview");
        assert!(
            active.cursor.trail_enabled,
            "negative control: trail is authored"
        );
        assert!(active.post_fx.bloom, "negative control: bloom is authored");
        assert!(
            active.post_fx.fire_shimmer,
            "negative control: fire shimmer is authored"
        );

        let serious_motion = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let serious = renderer_preview_spec(&state, 100, serious_motion, 13.0, theme)
            .expect("serious cursor preview remains available");
        assert!(serious.reduced_motion);
        assert!(!serious.cursor.trail_enabled);
        assert!(!serious.post_fx.bloom);
        assert!(!serious.post_fx.fire_shimmer);
        assert!(!serious.post_fx.hdr_glow);
        assert_eq!(serious.post_fx.sdr_boost, 0.0);
        assert_eq!(serious.animation(), PreviewAnimation::None);
        assert!(preview_reduced_motion(&state, serious_motion));
        assert_ne!(active.paint_fingerprint(), serious.paint_fingerprint());
    }

    #[test]
    fn serious_mode_trail_picker_previews_the_atomic_post_commit_candidate() {
        let config: Config = toml::from_str(
            "serious_mode = true\ncursor_trail = true\ncursor_trail_style = \"fire\"\n",
        )
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .unwrap();
        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes).unwrap(),
            SettingsState::display_value(field),
            state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE),
            field.seed.is_some(),
            &effective_default_for_field(prefs::EDIT_CURSOR_TRAIL_STYLE),
            &state.assets.themes,
        );
        let water = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("water"))
            .unwrap();
        let off = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("off"))
            .unwrap();
        state.choice_picker = Some(picker);
        let serious = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let theme = aterm_render::Theme::default();

        let focus_candidate = |state: &mut SettingsViewState, index: usize| {
            let picker = state.choice_picker.as_mut().unwrap();
            let page_size = picker.page_size.get();
            picker.offset.set((index / page_size) * page_size);
            state.common.hovered = None;
            state.common.last_focus = Some(UiKey::new(format!(
                "settings/choice/{}/{index}",
                prefs::EDIT_CURSOR_TRAIL_STYLE
            )));
        };
        focus_candidate(&mut state, water);
        let focused = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(focused.cursor.trail_enabled);
        assert!(!focused.reduced_motion);
        assert_eq!(focused.cursor.trail_style, PreviewTrailStyle::Water);
        assert!(focused.post_fx.motion_reason.contains("post-commit"));

        state.common.last_focus = Some(UiKey::new("settings/control/cursor_trail_style"));
        state.common.hovered = Some(UiKey::new(format!(
            "settings/choice/{}/{water}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )));
        let hovered = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(hovered.cursor.trail_enabled);
        assert_eq!(hovered.cursor.trail_style, PreviewTrailStyle::Water);

        focus_candidate(&mut state, off);
        let off_candidate = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(!off_candidate.cursor.trail_enabled);
        assert!(off_candidate.reduced_motion);
        assert!(field_bool(&state, prefs::EDIT_SERIOUS_MODE, false));
    }

    #[test]
    fn compact_top_settings_keeps_serious_mode_disclosure_semantically_reachable() {
        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let service = VersionedConfigService::new("serious_mode = true\n".to_string()).unwrap();
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
            let mut cx = view_cx_at(width, height);
            cx.motion.serious = true;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            compiled.validate_parity().unwrap();
            let disclosure = compiled
                .semantic(&UiKey::new("settings/top/serious-mode"))
                .expect("compact Serious Mode disclosure");
            assert!(disclosure.label.contains("keeps every other effect off"));
            assert!(disclosure.rect.x >= -0.01 && disclosure.rect.y >= -0.01);
            assert!(disclosure.rect.right() <= width + 0.01);
            assert!(disclosure.rect.bottom() <= height + 0.01);
            assert!(
                compiled
                    .paint
                    .iter()
                    .any(|node| node.key == UiKey::new("settings/top/serious-mode/visual")),
                "{width}×{height} keeps a bounded visual status"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/top/serious-mode/visual"))
                    .is_none(),
                "{width}×{height} publishes only the complete status"
            );
            for hit in &compiled.hits {
                assert!(
                    hit.rect.right() <= width + 0.01,
                    "{width}×{height}: {hit:?}"
                );
                assert!(
                    hit.rect.bottom() <= height + 0.01,
                    "{width}×{height}: {hit:?}"
                );
            }
        }
    }

    #[test]
    fn top_settings_paints_direct_labels_but_keeps_complete_label_semantics() {
        let (runtime, _instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_THEME)
            .unwrap();
        let expected_visual = field.label.to_string();
        let row = top_setting_row(
            state,
            prefs::EDIT_THEME,
            None,
            SettingsWidth::Wide,
            LogicalRect::new(0.0, 0.0, 900.0, 80.0),
        )
        .unwrap();
        let compiled = UiTree::new(row)
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
            .unwrap();
        let wrapper_key = UiKey::new(format!("settings/label/{}", prefs::EDIT_THEME));
        let semantic = compiled.semantic(&wrapper_key).unwrap();
        assert!(semantic.label.contains("Default"), "{}", semantic.label);
        let visual_key = UiKey::new(format!("settings/label/{}/visual", prefs::EDIT_THEME));
        let visual = compiled
            .paint
            .iter()
            .find_map(|node| {
                (node.key == visual_key)
                    .then_some(&node.content)
                    .and_then(|content| {
                        let UiContent::Text(spec) = content else {
                            return None;
                        };
                        Some(spec.text.as_str())
                    })
            })
            .unwrap();
        assert_eq!(visual, expected_visual);
        assert!(!visual.contains("Default"));
        assert!(!visual.contains("Override"));
        assert!(compiled.semantic(&visual_key).is_none());
    }

    #[test]
    fn music_suppression_resolver_covers_every_reason_and_priority() {
        let motion = crate::native_app::ViewMotionCx::default();
        let state = |config: Config| SettingsViewState::new(&config);

        assert_eq!(
            top_music_suppression_reason_for_output(&state(Config::default()), motion, false),
            Some("Saved On for macOS; audio output is unavailable on this platform.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sounds: Some(false),
                    ..Config::default()
                }),
                motion,
                false,
            ),
            Some("Saved Off; audio output is unavailable on this platform.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sounds: Some(false),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            None,
            "an authored Off switch is not described as suppressed"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    serious_mode: Some(true),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            None,
            "Serious Mode projects the switch Off instead of claiming it is On"
        );

        let all_runtime_suppressions = crate::native_app::ViewMotionCx {
            focused: false,
            system_reduced: true,
            performance_reduced: true,
            ..motion
        };
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    cursor_trail_style: Some("off".to_string()),
                    trail_sound_volume: Some(0.0),
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent because Cursor trail is Off."),
            "trail Off has priority over every later runtime suppression"
        );
        for style in ["not-a-trail", "pack:missing"] {
            let reason = top_music_suppression_reason_for_output(
                &state(Config {
                    cursor_trail_style: Some(style.to_string()),
                    ..Config::default()
                }),
                motion,
                true,
            );
            assert_eq!(
                reason,
                Some("On, currently silent because Cursor trail style is unavailable."),
                "{style:?} has no admitted trail/audio runtime"
            );
            assert_eq!(
                reason.map(top_music_suppression_visual),
                Some("Trail unavailable")
            );
        }
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sound_volume: Some(0.0),
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent because trail sound volume is 0."),
            "zero volume has priority over focus and motion"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent while this window is unfocused."),
            "window focus has priority over motion"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            Some("On, currently suppressed by Motion: Reduced.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config::default()),
                crate::native_app::ViewMotionCx {
                    system_reduced: true,
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            Some("On, currently suppressed by system Reduce Motion."),
            "system policy has priority over the adaptive limiter"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config::default()),
                crate::native_app::ViewMotionCx {
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            Some("On, currently suppressed by adaptive performance mode.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    load_adaptive_motion: Some(false),
                    ..Config::default()
                }),
                crate::native_app::ViewMotionCx {
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            None,
            "the authored adaptive-motion opt-out is respected"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("full".to_string()),
                    ..Config::default()
                }),
                crate::native_app::ViewMotionCx {
                    system_reduced: true,
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            None,
            "explicit Full overrides system and adaptive reduction"
        );
    }

    #[test]
    fn music_effects_discloses_effective_motion_suppression_without_rewriting_toggle() {
        let auto = SettingsViewState::new(&Config::default());
        if crate::trail_audio::output_available() {
            let mut system_reduced = crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            };
            assert_eq!(
                top_music_suppression_reason(&auto, system_reduced),
                Some("On, currently suppressed by system Reduce Motion.")
            );
            system_reduced.performance_reduced = true;
            system_reduced.system_reduced = false;
            assert_eq!(
                top_music_suppression_reason(&auto, system_reduced),
                Some("On, currently suppressed by adaptive performance mode.")
            );

            let reduced = SettingsViewState::new(&Config {
                motion: Some("reduced".to_string()),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(&reduced, crate::native_app::ViewMotionCx::default()),
                Some("On, currently suppressed by Motion: Reduced.")
            );
            let full = SettingsViewState::new(&Config {
                motion: Some("full".to_string()),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(
                    &full,
                    crate::native_app::ViewMotionCx {
                        system_reduced: true,
                        performance_reduced: true,
                        ..crate::native_app::ViewMotionCx::default()
                    }
                ),
                None,
                "explicit Full overrides system/adaptive reduction while focused"
            );
        } else {
            assert_eq!(
                top_music_suppression_reason(&auto, crate::native_app::ViewMotionCx::default()),
                Some("Saved On for macOS; audio output is unavailable on this platform.")
            );
            let off = SettingsViewState::new(&Config {
                trail_sounds: Some(false),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(&off, crate::native_app::ViewMotionCx::default()),
                Some("Saved Off; audio output is unavailable on this platform.")
            );
        }
        assert!(
            top_projected_music_value(&auto),
            "authored switch remains On"
        );

        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!()
                };
                state.reduce_page_scroll(5, SettingsPageScrollCommand::Absolute(3));
            }
            let mut cx = view_cx_at(width, height);
            cx.motion.system_reduced = true;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let status = compiled
                .semantic(&UiKey::new("settings/top/music-effects/suppression"))
                .expect("compact Music page carries its own suppression status");
            assert!(
                status
                    .label
                    .contains(if crate::trail_audio::output_available() {
                        "system Reduce Motion"
                    } else {
                        "audio output is unavailable"
                    })
            );
            let toggle = compiled
                .semantic(&UiKey::new(format!(
                    "settings/control/{}",
                    prefs::EDIT_TRAIL_SOUNDS
                )))
                .unwrap();
            assert_eq!(toggle.value, SemanticValue::Bool(true));
        }
    }

    #[test]
    fn compact_serious_trail_picker_keeps_disclosure_preview_and_every_choice_reachable() {
        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let service = VersionedConfigService::new("serious_mode = true\n".to_string()).unwrap();
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!(
                            "settings/set/{}",
                            prefs::EDIT_CURSOR_TRAIL_STYLE
                        )),
                        value: None,
                    }),
                )
                .unwrap();

            let mut cx = view_cx_at(width, height);
            cx.motion.serious = true;
            let mut seen = BTreeSet::new();
            for _ in 0..16 {
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                compiled.validate_parity().unwrap();
                for key in [
                    "settings/top/serious-mode",
                    "settings/top/choice-preview",
                    "settings/choice-close",
                    "settings/choice-page-prev",
                    "settings/choice-page-next",
                ] {
                    let node = compiled
                        .semantic(&UiKey::new(key))
                        .unwrap_or_else(|| panic!("{width}×{height} picker is missing {key}"));
                    assert!(node.rect.right() <= width + 0.01, "{key}: {:?}", node.rect);
                    assert!(
                        node.rect.bottom() <= height + 0.01,
                        "{key}: {:?}",
                        node.rect
                    );
                }
                for node in &compiled.semantics {
                    if node.key.as_str().starts_with(&format!(
                        "settings/choice/{}/",
                        prefs::EDIT_CURSOR_TRAIL_STYLE
                    )) {
                        seen.insert(node.key.as_str().to_string());
                    }
                }
                for hit in &compiled.hits {
                    assert!(
                        hit.rect.right() <= width + 0.01,
                        "{width}×{height}: {hit:?}"
                    );
                    assert!(
                        hit.rect.bottom() <= height + 0.01,
                        "{width}×{height}: {hit:?}"
                    );
                }
                let next = compiled
                    .semantic(&UiKey::new("settings/choice-page-next"))
                    .and_then(|node| node.state.as_ref())
                    .is_some_and(|state| state.enabled);
                if !next {
                    break;
                }
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new("settings/choice-page-next"),
                            value: None,
                        }),
                    )
                    .unwrap();
            }
            let AppViewState::Settings(state) = runtime.view_state(view).unwrap() else {
                unreachable!()
            };
            assert_eq!(
                seen.len(),
                state.choice_picker.as_ref().unwrap().options.len(),
                "{width}×{height} reaches every trail choice"
            );
        }
    }

    #[test]
    fn highlighted_motion_candidate_resolves_against_live_host_facts_before_commit() {
        let config: Config = toml::from_str("motion = \"reduced\"\n").unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_MOTION)
            .expect("motion field");
        let picker = ChoicePicker::new(
            prefs::EDIT_MOTION,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
                .expect("motion choices"),
            SettingsState::display_value(field),
            true,
            true,
            &effective_default_for_field(prefs::EDIT_MOTION),
            &state.assets.themes,
        );
        state.choice_picker = Some(picker);
        let focus = |state: &mut SettingsViewState, value: &str| {
            let picker = state.choice_picker.as_mut().unwrap();
            let index = picker
                .options
                .iter()
                .position(|option| option.value.as_deref() == Some(value))
                .unwrap();
            picker
                .offset
                .set((index / ChoicePicker::PAGE_SIZE) * ChoicePicker::PAGE_SIZE);
            state.common.last_focus = Some(UiKey::new(format!(
                "settings/choice/{}/{index}",
                prefs::EDIT_MOTION
            )));
        };

        let constrained = crate::native_app::ViewMotionCx {
            system_reduced: true,
            focused: true,
            performance_reduced: true,
            system_dark: false,
            serious: false,
        };
        focus(&mut state, "full");
        assert!(
            !preview_reduced_motion(&state, constrained),
            "highlighted Full overrides OS and adaptive reduction"
        );
        focus(&mut state, "auto");
        assert!(preview_reduced_motion(&state, constrained));
        focus(&mut state, "reduced");
        assert!(preview_reduced_motion(
            &state,
            crate::native_app::ViewMotionCx::default()
        ));

        focus(&mut state, "auto");
        let load_only = crate::native_app::ViewMotionCx {
            system_reduced: false,
            focused: true,
            performance_reduced: true,
            system_dark: false,
            serious: false,
        };
        assert!(preview_reduced_motion(&state, load_only));
        state
            .legacy
            .fields
            .iter_mut()
            .find(|field| field.key == prefs::EDIT_LOAD_ADAPTIVE_MOTION)
            .unwrap()
            .seed = Some("false".to_string());
        assert!(!preview_reduced_motion(&state, load_only));

        focus(&mut state, "full");
        assert!(preview_reduced_motion(
            &state,
            crate::native_app::ViewMotionCx {
                focused: false,
                ..crate::native_app::ViewMotionCx::default()
            }
        ));
        assert_eq!(
            state.raw_value(prefs::EDIT_MOTION).as_deref(),
            Some("reduced")
        );
    }

    fn setup() -> (
        NativeRuntime,
        crate::native_app::AppInstanceId,
        crate::native_app::ViewId,
    ) {
        setup_with_update(UpdateState::from_status(1, "0.1.0", None, false))
    }

    fn setup_with_update(
        update: UpdateState,
    ) -> (
        NativeRuntime,
        crate::native_app::AppInstanceId,
        crate::native_app::ViewId,
    ) {
        let app = SettingsApp::new(update);
        let mut runtime = NativeRuntime::new();
        let instance = runtime.insert_instance(NativeApp::Settings(app)).unwrap();
        let mut core_views = ViewStore::default();
        let view = core_views.insert_native(instance).unwrap();
        runtime
            .attach_view(
                view,
                instance,
                AppViewState::Settings(Box::new(SettingsViewState::new(&Config::default()))),
            )
            .unwrap();
        (runtime, instance, view)
    }

    fn replace_settings_source(
        runtime: &mut NativeRuntime,
        view: crate::native_app::ViewId,
        source: String,
    ) {
        let snapshot = VersionedConfigService::new(source)
            .expect("valid Settings fixture")
            .snapshot();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).expect("project Settings fixture");
    }

    fn update_status(staged: bool) -> aterm_update::UpdateStatus {
        aterm_update::UpdateStatus {
            enabled: true,
            current_build: 1,
            staged_build: staged.then_some(2),
            staged_version: staged.then(|| "0.2.0".to_string()),
            staged_commit: staged.then(|| "deadbeef".to_string()),
            staged_dmg_sha256: staged.then(|| "0".repeat(64)),
            changelog: staged
                .then(|| "### Better\n- compact Settings\n- semantic previews".to_string()),
            outcome: "Update service healthy".to_string(),
            updated_at: String::new(),
            failing_checks: 0,
            failing_kind: String::new(),
            failing_applies: 0,
            installable: true,
            failing_since: String::new(),
            failing_persistent: false,
            rescues: 0,
            failing_checks_kind: String::new(),
            channel_unreadable: false,
        }
    }

    fn view_cx() -> ViewCx<'static> {
        view_cx_at(1_200.0, 820.0)
    }

    fn view_cx_at(width: f32, height: f32) -> ViewCx<'static> {
        // NativeRuntime view tests bypass App/backend construction. Opt into
        // the exact host-prepared UI faces at this direct-view fixture boundary
        // instead of changing the cold font-store constructor under cfg(test).
        crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
        ViewCx {
            viewport: LogicalRect::new(0.0, 0.0, width, height),
            config_revision: 1,
            update_revision: 1,
            animation_phase_ms: 720,
            motion: crate::native_app::ViewMotionCx::default(),
            terminal_font_px: 12.0,
            terminal_theme: aterm_render::Theme::default(),
            semantic_font: None,
            document: None,
        }
    }

    fn compile_settings_view(
        runtime: &NativeRuntime,
        instance: crate::native_app::AppInstanceId,
        view: crate::native_app::ViewId,
        cx: &ViewCx<'_>,
    ) -> crate::native_ui::CompiledUi {
        runtime
            .render(instance, view, cx)
            .expect("Settings renders")
            .compile(cx.viewport)
            .expect("Settings compiles")
    }

    /// The Home page's welcome flourish: on a roomy host the rainbow banner is
    /// present with a descriptive semantic label, decorative (no action,
    /// unfocusable), and paint-clean; ornamental chrome yields on short hosts
    /// and under Serious Mode.
    #[test]
    fn top_settings_rainbow_banner_present_and_yielding() {
        let key = UiKey::new("settings/top/rainbow");
        let (runtime, instance, view) = setup();
        let cx = view_cx_at(1_200.0, 810.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let node = compiled
            .semantic(&key)
            .expect("roomy Home page shows the rainbow banner");
        assert_eq!(node.label, "A rainbow arcs over the settings");
        assert!(node.action.is_none(), "the banner is pure decoration");
        assert_zero_top_paint(&compiled, "rainbow banner at 1200x810 1x");

        // A host below the fit gate keeps today's exact layout.
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 700.0));
        assert!(
            compiled.semantic(&key).is_none(),
            "short hosts must not gain the banner"
        );

        // Serious Mode hides the unapologetically playful.
        let mut serious = view_cx_at(1_200.0, 810.0);
        serious.motion = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let compiled = compile_settings_view(&runtime, instance, view, &serious);
        assert!(
            compiled.semantic(&key).is_none(),
            "Serious Mode must not show the banner"
        );
    }

    fn assert_zero_top_paint(compiled: &crate::native_ui::CompiledUi, context: &str) {
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        let audit = compiled.paint_audit_lines();
        let summary = audit.first().expect("paint audit summary");
        let failures = audit
            .iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .cloned()
            .collect::<Vec<_>>();
        assert!(
            summary.contains("overflow=0") && summary.contains("clipped=0"),
            "{context}: {summary}\n{}",
            audit.join("\n")
        );
        assert!(
            failures.is_empty(),
            "{context}: renderer text overflow or clip:\n{}",
            failures.join("\n")
        );
        for node in compiled
            .semantics
            .iter()
            .filter(|node| node.action.is_some())
        {
            assert!(
                node.rect.x >= compiled.bounds.x - 0.01
                    && node.rect.y >= compiled.bounds.y - 0.01
                    && node.rect.right() <= compiled.bounds.right() + 0.01
                    && node.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: actionable {:?} escapes {:?}: {:?}",
                node.key,
                compiled.bounds,
                node.rect
            );
        }
    }

    fn assert_picker_descendants_contained(
        compiled: &crate::native_ui::CompiledUi,
        key: &str,
        context: &str,
    ) {
        let picker = compiled
            .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
            .unwrap_or_else(|| panic!("{context}: missing picker"));
        let contains = |rect: LogicalRect| {
            rect.x >= picker.rect.x - 0.01
                && rect.y >= picker.rect.y - 0.01
                && rect.right() <= picker.rect.right() + 0.01
                && rect.bottom() <= picker.rect.bottom() + 0.01
        };
        for node in compiled.semantics.iter().filter(|node| {
            node.key.as_str().starts_with("settings/choice/")
                || matches!(
                    node.key.as_str(),
                    "settings/choice-close"
                        | "settings/choice-page-prev"
                        | "settings/choice-page-next"
                )
        }) {
            assert!(
                contains(node.rect),
                "{context}: semantic {:?} escapes picker {:?}: {:?}",
                node.key,
                picker.rect,
                node.rect
            );
        }
        for hit in compiled.hits.iter().filter(|hit| {
            hit.key.as_str().starts_with("settings/choice/")
                || matches!(
                    hit.key.as_str(),
                    "settings/choice-close"
                        | "settings/choice-page-prev"
                        | "settings/choice-page-next"
                )
        }) {
            assert!(
                contains(hit.rect),
                "{context}: hit {:?} escapes picker {:?}: {:?}",
                hit.key,
                picker.rect,
                hit.rect
            );
        }
    }

    fn assert_material_hit(compiled: &crate::native_ui::CompiledUi, key: &str, context: &str) {
        let semantic = compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{context}: missing semantic action {key}"));
        assert!(
            semantic.action.is_some(),
            "{context}: {key} lost its semantic action"
        );
        let hit = compiled
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == key)
            .unwrap_or_else(|| panic!("{context}: missing hit region {key}"));
        assert!(
            hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
            "{context}: {key} is not a material hit target: {:?}",
            hit.rect
        );
        assert!(
            hit.rect.x >= compiled.bounds.x - 0.01
                && hit.rect.y >= compiled.bounds.y - 0.01
                && hit.rect.right() <= compiled.bounds.right() + 0.01
                && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: {key} hit escapes {:?}: {:?}",
            compiled.bounds,
            hit.rect
        );
    }

    fn assert_all_hits_material_and_contained(
        compiled: &crate::native_ui::CompiledUi,
        context: &str,
    ) {
        for hit in &compiled.hits {
            assert!(
                hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
                "{context}: {:?} is not a material hit target: {:?}",
                hit.key,
                hit.rect
            );
            assert!(
                hit.rect.x >= compiled.bounds.x - 0.01
                    && hit.rect.y >= compiled.bounds.y - 0.01
                    && hit.rect.right() <= compiled.bounds.right() + 0.01
                    && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: {:?} hit escapes {:?}: {:?}",
                hit.key,
                compiled.bounds,
                hit.rect
            );
        }
    }

    fn assert_short_landscape_geometry(
        compiled: &crate::native_ui::CompiledUi,
        scale: f32,
        context: &str,
    ) {
        const WIDTH: f32 = 568.0;
        const HEIGHT: f32 = 320.0;
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        for semantic in compiled
            .semantics
            .iter()
            .filter(|semantic| semantic.action.is_some())
        {
            assert!(
                semantic.rect.x >= -0.01
                    && semantic.rect.y >= -0.01
                    && semantic.rect.right() <= WIDTH + 0.01
                    && semantic.rect.bottom() <= HEIGHT + 0.01,
                "{context}: actionable semantic {:?} escapes the viewport: {:?}",
                semantic.key,
                semantic.rect
            );
            if scale >= 2.0 {
                assert!(
                    semantic.rect.height >= scaled_control_height_at_scale(2.0) - 0.01,
                    "{context}: {:?} was clipped below its 2× control allocation: {:?}",
                    semantic.key,
                    semantic.rect
                );
            }
        }
        for hit in &compiled.hits {
            let paint = compiled
                .paint
                .iter()
                .find(|paint| paint.key == hit.key)
                .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
            assert_eq!(paint.rect, hit.rect, "{context}: {:?} hit parity", hit.key);
            assert!(
                hit.rect.x >= -0.01
                    && hit.rect.y >= -0.01
                    && hit.rect.right() <= WIDTH + 0.01
                    && hit.rect.bottom() <= HEIGHT + 0.01,
                "{context}: {:?} escapes the viewport: {:?}",
                hit.key,
                hit.rect
            );
        }
    }

    fn assert_accessible_pager(
        compiled: &crate::native_ui::CompiledUi,
        key: &str,
        page: usize,
        total: usize,
        context: &str,
    ) {
        assert!(total > 1);
        let previous = compiled
            .semantic(&UiKey::new(format!("{key}/previous")))
            .unwrap_or_else(|| panic!("{context}: missing accessible Previous"));
        let next = compiled
            .semantic(&UiKey::new(format!("{key}/next")))
            .unwrap_or_else(|| panic!("{context}: missing accessible Next"));
        assert_eq!(
            previous.state.expect("pager state").enabled,
            page > 0,
            "{context}: Previous enabled state"
        );
        assert_eq!(
            next.state.expect("pager state").enabled,
            page + 1 < total,
            "{context}: Next enabled state"
        );
    }

    fn pager_total(compiled: &crate::native_ui::CompiledUi, status_key: &str) -> usize {
        compiled
            .semantic(&UiKey::new(status_key))
            .unwrap_or_else(|| panic!("missing pager status {status_key}"))
            .label
            .rsplit_once(" of ")
            .and_then(|(_, total)| total.parse::<usize>().ok())
            .unwrap_or_else(|| panic!("invalid pager status {status_key}"))
    }

    #[test]
    fn smart_title_health_is_runtime_backed_and_transport_truthful() {
        let (mut runtime, instance, view) = setup();
        let health = TitleSummaryHealth {
            state: TitleSummaryRuntimeState::Error,
            provider: crate::app_config::TitleSummaryProvider::Ollama,
            model: Some("qwen3.5:4b-q4_K_M".to_string()),
            endpoint: Some("http://127.0.0.1:11434/api/chat".to_string()),
            locality: TitleSummaryLocality::UnattestedLoopback,
            managed_install_present: false,
            model_ready: false,
            last_error: Some("managed runtime is not installed".to_string()),
            next_retry_after: Some(std::time::Duration::from_secs(9)),
            next_refresh_after: None,
            timeout: Some(std::time::Duration::from_secs(42)),
            proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
            ca_file: None,
        };
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::WindowTabs);
            assert!(state.replace_title_summary_health(health.clone()));
            assert!(!state.replace_title_summary_health(health));
        }

        let cx = view_cx();
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let label = |key: &str| {
            compiled
                .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
                .unwrap_or_else(|| panic!("missing Smart Titles health row {key}"))
                .label
                .clone()
        };
        assert!(label("state").contains("Needs attention"));
        assert!(label("locality").contains("not proof of local-only"));
        assert!(label("transport").contains("42s timeout"));
        assert!(label("transport").contains("direct connection (forced)"));
        assert!(label("transport").contains("TLS/CA not used"));
        assert!(label("readiness").contains("no automatic download"));
        assert!(label("readiness").contains("latest request has not confirmed model readiness"));
        assert!(label("detail").contains("managed runtime is not installed"));
        assert!(label("detail").contains("Error retry"));
        assert!(label("precedence").contains("Authored Description wins"));

        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.replace_title_summary_health(TitleSummaryHealth {
                state: TitleSummaryRuntimeState::Ready,
                provider: crate::app_config::TitleSummaryProvider::OpenAiCompatible,
                model: Some("private-model".to_string()),
                endpoint: Some("https://127.0.0.1:9443/v1/chat/completions".to_string()),
                locality: TitleSummaryLocality::UnattestedLoopback,
                managed_install_present: false,
                model_ready: true,
                last_error: None,
                next_retry_after: None,
                next_refresh_after: Some(std::time::Duration::from_secs(30)),
                timeout: Some(std::time::Duration::from_secs(20)),
                proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
                ca_file: Some("/tmp/private-model-ca.pem".to_string()),
            });
        }
        let openai = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let openai_transport = openai
            .semantic(&UiKey::new("settings/smart-titles/health/transport"))
            .unwrap()
            .label
            .clone();
        assert!(openai_transport.contains("direct connection"));
        assert!(openai_transport.contains("platform roots replaced"));
        let openai_detail = openai
            .semantic(&UiKey::new("settings/smart-titles/health/detail"))
            .unwrap()
            .label
            .clone();
        assert!(openai_detail.contains("Routine activity refresh"));

        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let compact_cx = view_cx_at(width, height);
            let compact = runtime
                .render(instance, view, &compact_cx)
                .unwrap()
                .compile(compact_cx.viewport)
                .unwrap();
            let keys = if height <= 420.0 {
                vec!["state", "summary"]
            } else {
                vec![
                    "state",
                    "locality",
                    "transport",
                    "readiness",
                    "detail",
                    "precedence",
                ]
            };
            for key in keys {
                let node = compact
                    .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
                    .unwrap_or_else(|| panic!("{width}×{height} loses health row {key}"));
                assert!(
                    node.rect.bottom() <= compact_cx.viewport.bottom() + 0.01,
                    "{width}×{height} clips health row {key}: {:?}",
                    node.rect
                );
            }
        }
    }

