    #[test]
    fn bounded_numeric_rows_disclose_configured_and_effective_without_rewriting_raw() {
        let config = Config {
            font_px: Some(500.0),
            line_height: Some(9.0),
            font_weight: Some(0),
            ..Config::default()
        };
        let state = SettingsViewState::new(&config);
        for (key, configured, effective, outcome) in [
            (
                prefs::EDIT_FONT_PX,
                "500",
                f64::from(crate::FONT_PX),
                "ignored",
            ),
            (prefs::EDIT_LINE_HEIGHT, "9", 2.0, "runtime clamps"),
            (prefs::EDIT_FONT_WEIGHT, "0", 1.0, "runtime clamps"),
        ] {
            let (index, field) = state
                .legacy
                .fields
                .iter()
                .enumerate()
                .find(|(_, field)| field.key == key)
                .unwrap();
            assert_eq!(field.seed.as_deref(), Some(configured));
            assert_eq!(state.raw_value(key).as_deref(), Some(configured));
            assert_eq!(
                numeric_slider_value_for_state(&state, field).unwrap().0,
                effective
            );
            let disclosure = bounded_numeric_disclosure(&state, field, false).unwrap();
            assert!(
                disclosure
                    .semantic
                    .contains(&format!("configured {configured}"))
            );
            assert!(disclosure.semantic.contains(outcome));

            let compiled = UiTree::new(setting_row(
                &state,
                index,
                field,
                true,
                false,
                SettingsWidth::Wide,
            ))
            .compile(LogicalRect::new(0.0, 0.0, 1_000.0, 90.0))
            .unwrap();
            let control = compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap();
            assert!(control.label.contains(&format!("configured {configured}")));
            assert!(matches!(
                &control.value,
                SemanticValue::Number { value, .. } if *value == effective
            ));
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/label/{key}")))
                    .unwrap()
                    .label
                    .contains(&format!("Configured {configured}")),
                "Modified must visibly retain the authored value for {key}"
            );
        }

        let off_step = Config {
            line_height: Some(1.03),
            ..Config::default()
        };
        let off_step = SettingsViewState::new(&off_step);
        let field = off_step
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_LINE_HEIGHT)
            .unwrap();
        assert_eq!(
            numeric_slider_value(field),
            Some((1.03, "1.03".to_string())),
            "step is an interaction increment, not a validity constraint"
        );
        assert_eq!(bounded_numeric_submission_error(field, Some("1.03")), None);
    }

    #[test]
    fn bounded_native_float_non_finite_values_keep_sliders_and_disclose() {
        let mut state = SettingsViewState::new(&Config::default());
        let expected = BTreeMap::from([
            (prefs::EDIT_FONT_PX, f64::from(crate::FONT_PX)),
            (prefs::EDIT_LINE_HEIGHT, 1.0),
            (prefs::EDIT_MINIMUM_CONTRAST, 1.0),
            (
                prefs::EDIT_FAINT_OPACITY,
                f64::from(aterm_types::DIM_FACTOR),
            ),
            (prefs::EDIT_STEM_GAMMA, 1.0),
            (prefs::EDIT_CURSOR_TRAIL_INTENSITY, 0.0),
            (prefs::EDIT_CURSOR_TRAIL_RADIUS, 0.0),
            (prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH, 0.0),
            (prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS, 2.2),
            (prefs::EDIT_CURSOR_GLOW_SDR_BOOST, 0.0),
            (prefs::EDIT_TRAIL_SOUND_VOLUME, 0.0),
            (prefs::EDIT_FONT_WEIGHT_DARK_NUDGE, 0.0),
            (prefs::EDIT_BACKGROUND_OPACITY, 1.0),
            (prefs::EDIT_WALLPAPER_DIM, 0.3),
            (prefs::EDIT_WINDOW_PADDING, f64::from(crate::PAD_LOGICAL_PX)),
            (
                prefs::EDIT_WINDOW_PADDING_TOP,
                f64::from(crate::PAD_TOP_LOGICAL_PX),
            ),
            ("sparkle_words.profanity.intensity", 0.0),
            ("sparkle_words.ink.strength", 0.0),
        ]);
        let discovered = state
            .legacy
            .fields
            .iter()
            .filter(|field| {
                matches!(field.kind, EditKind::Float)
                    && prefs::range_of(field.key).is_some()
                    && settings_field_is_visible(field.key, true, false)
            })
            .map(|field| field.key)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            discovered,
            expected.keys().copied().collect(),
            "a new bounded native float needs an audited non-finite runtime projection"
        );

        for raw in ["NaN", "inf", "-inf"] {
            for (&key, &effective) in &expected {
                let index = state
                    .legacy
                    .fields
                    .iter()
                    .position(|field| field.key == key)
                    .unwrap();
                state.legacy.fields[index].seed = Some(raw.to_string());
                state.raw_values.insert(key.to_string(), raw.to_string());
                let field = &state.legacy.fields[index];
                assert_eq!(
                    numeric_slider_value_for_state(&state, field).unwrap().0,
                    effective,
                    "{key} {raw}"
                );
                let disclosure = bounded_numeric_disclosure(&state, field, false).unwrap();
                assert!(disclosure.semantic.contains(raw), "{key} {raw}");
                assert!(disclosure.semantic.contains("non-finite"), "{key} {raw}");
                assert!(
                    bounded_numeric_submission_error(field, Some(raw))
                        .unwrap()
                        .contains("must be finite"),
                    "{key} {raw}"
                );

                let compiled = UiTree::new(setting_row(
                    &state,
                    index,
                    field,
                    true,
                    false,
                    SettingsWidth::Wide,
                ))
                .compile(LogicalRect::new(0.0, 0.0, 1_100.0, 90.0))
                .unwrap();
                let control = compiled
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .unwrap();
                assert!(control.label.contains("non-finite"), "{key} {raw}");
                assert!(matches!(
                    &control.value,
                    SemanticValue::Number { value, .. } if *value == effective
                ));
            }
        }
    }

