    #[test]
    fn compact_switch_is_trailing_touch_sized_and_never_a_full_width_bar() {
        for (viewport_width, viewport_height) in [(390.0, 568.0), (474.0, 658.0)] {
            let (mut runtime, instance, view) = setup();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new("settings/search"),
                        value: Some(SemanticInput::Text("cursor blink".to_string())),
                    }),
                )
                .unwrap();
            let cx = view_cx_at(viewport_width, viewport_height);
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            let key = UiKey::new(format!("settings/control/{}", prefs::EDIT_CURSOR_BLINK));
            let control = compiled.semantic(&key).expect("visible compact switch");
            let controls = compiled
                .semantic(&UiKey::new(format!(
                    "settings/controls/{}",
                    prefs::EDIT_CURSOR_BLINK
                )))
                .expect("full compact control band");
            assert!(
                (control.rect.width - 104.0).abs() < 0.01,
                "switch width is {:?}",
                control.rect
            );
            assert!(control.rect.height >= 44.0, "switch is touch-sized");
            assert!(control.rect.width < controls.rect.width * 0.5);
            assert!(
                (control.rect.right() - controls.rect.right()).abs() < 0.01,
                "switch trails its row: control={:?}, row={:?}",
                control.rect,
                controls.rect
            );
            let hit = compiled
                .hits
                .iter()
                .find(|hit| hit.key == key)
                .expect("switch exports a hit action");
            assert_eq!(hit.rect, control.rect);
            let SemanticValue::Bool(current) = &control.value else {
                panic!("switch exports boolean state");
            };
            let action = hit.action.clone();
            let outcome = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: action,
                        value: Some(SemanticInput::Bool(!*current)),
                    }),
                )
                .unwrap();
            assert!(outcome.effects.iter().any(|effect| matches!(
                effect,
                AppEffect::ConfigPatch { patch, .. }
                    if patch.edits.first().is_some_and(|edit| edit.key == prefs::EDIT_CURSOR_BLINK)
            )));
        }
    }

    #[test]
    fn compact_choice_picker_keeps_options_done_and_pagination_wholly_reachable() {
        for (viewport_width, viewport_height) in [
            // The ordinary 35-column Retina phone-width host presents an
            // exact 286.5-point semantic viewport. Keep it in the oracle so
            // page status copy cannot be squeezed by its sibling buttons.
            (286.5, 558.0),
            (320.0, 568.0),
            (390.0, 568.0),
            (474.0, 658.0),
        ] {
            let (mut runtime, instance, view) = setup();
            let open = || ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            };
            runtime
                .dispatch(instance, view, AppEvent::Action(open()))
                .unwrap();
            let cx = view_cx_at(viewport_width, viewport_height);
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            let picker = compiled
                .semantic(&UiKey::new(format!(
                    "settings/choice-picker/{}",
                    prefs::EDIT_THEME
                )))
                .expect("compact theme picker");
            assert!(
                picker.rect.x >= 0.0
                    && picker.rect.y >= 0.0
                    && picker.rect.right() <= viewport_width + 0.01
                    && picker.rect.bottom() <= viewport_height + 0.01,
                "picker is whole at {viewport_width}x{viewport_height}: {:?}",
                picker.rect
            );

            let option_prefix = format!("settings/choice/{}/", prefs::EDIT_THEME);
            let options = compiled
                .semantics
                .iter()
                .filter(|node| node.key.as_str().starts_with(&option_prefix))
                .collect::<Vec<_>>();
            assert_eq!(
                options.len(),
                ChoicePicker::preferred_page_size().min(3),
                "compact pagination uses its current Dynamic Type budget"
            );
            for option in &options {
                assert!(option.rect.height >= 44.0);
                assert!(option.rect.width >= 140.0);
                assert!(option.rect.x >= picker.rect.x);
                assert!(option.rect.right() <= picker.rect.right() + 0.01);
                assert!(option.rect.bottom() <= picker.rect.bottom() + 0.01);
                let paint = compiled
                    .paint
                    .iter()
                    .find(|paint| paint.key == option.key)
                    .expect("choice is painted");
                let hit = compiled
                    .hits
                    .iter()
                    .find(|hit| hit.key == option.key)
                    .expect("choice is activatable");
                assert_eq!(paint.rect, option.rect, "choice is not clipped");
                assert_eq!(hit.rect, option.rect, "choice hit is not clipped");
            }
            for (index, option) in options.iter().enumerate() {
                for other in options.iter().skip(index + 1) {
                    assert!(
                        option.rect.intersect(other.rect).is_none(),
                        "choice text surfaces never overlap: {:?} and {:?}",
                        option.rect,
                        other.rect
                    );
                }
            }

            let control = |key: &str| {
                compiled
                    .semantic(&UiKey::new(key))
                    .unwrap_or_else(|| panic!("missing {key}"))
            };
            for key in [
                "settings/choice-close",
                "settings/choice-page-prev",
                "settings/choice-page-next",
            ] {
                let node = control(key);
                assert!(node.rect.height >= 44.0, "{key} is touch-sized");
                assert!(node.rect.bottom() <= picker.rect.bottom() + 0.01);
                assert!(node.rect.bottom() <= viewport_height + 0.01);
            }
            let page_label = control(&format!("settings/choice-page-label/{}", prefs::EDIT_THEME));
            let page_copy = "Page 1 of 7";
            let page_copy_width = crate::tray_raster::ui_text_width(page_copy, 13.0);
            assert!(
                page_label.rect.width + 0.01 >= page_copy_width,
                "{viewport_width}px picker clips {page_copy:?}: {:.1}px available, {page_copy_width:.1}px required",
                page_label.rect.width,
            );
            let close_action = compiled
                .hits
                .iter()
                .find(|hit| hit.key.as_str() == "settings/choice-close")
                .expect("Done is activatable")
                .action
                .clone();
            let next_action = compiled
                .hits
                .iter()
                .find(|hit| hit.key.as_str() == "settings/choice-page-next")
                .expect("Next is activatable")
                .action
                .clone();
            assert!(
                compiled
                    .hits
                    .iter()
                    .all(|hit| hit.key.as_str() != "settings/choice-page-prev"),
                "disabled Previous does not claim a hit"
            );

            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: close_action,
                        value: None,
                    }),
                )
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                panic!("Settings view");
            };
            assert!(state.choice_picker.is_none(), "Done closes the picker");
            let theme_control = UiKey::new(format!("settings/control/{}", prefs::EDIT_THEME));
            assert_eq!(state.common.last_focus.as_ref(), Some(&theme_control));
            let closed = compile_settings_view(&runtime, instance, view, &cx);
            assert!(
                closed.focus_order.contains(&theme_control),
                "Done returns focus to the setting that opened the picker"
            );

            runtime
                .dispatch(instance, view, AppEvent::Action(open()))
                .unwrap();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: next_action,
                        value: None,
                    }),
                )
                .unwrap();
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            let first_next_key = UiKey::new(format!(
                "settings/choice/{}/{}",
                prefs::EDIT_THEME,
                ChoicePicker::PAGE_SIZE
            ));
            let first_next = compiled
                .hits
                .iter()
                .find(|hit| hit.key == first_next_key)
                .expect("next page is visible and activatable");
            assert!(
                compiled
                    .hits
                    .iter()
                    .any(|hit| hit.key.as_str() == "settings/choice-page-prev")
            );
            let outcome = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: first_next.action.clone(),
                        value: None,
                    }),
                )
                .unwrap();
            assert!(outcome.effects.iter().any(|effect| matches!(
                effect,
                AppEffect::ConfigPatch { patch, .. }
                    if patch.edits.first().is_some_and(|edit| edit.key == prefs::EDIT_THEME)
            )));
        }
    }

    #[test]
    fn compact_special_routes_semantically_page_to_every_action_and_value() {
        for viewport_width in [320.0, 390.0] {
            let cx = view_cx_at(viewport_width, 568.0);

            let (mut runtime, instance, view) = setup();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(SettingsRoute::About),
                        value: None,
                    }),
                )
                .unwrap();
            let mut about_keys = BTreeSet::new();
            let about_sections = compact_about_section_count();
            for section in 0..about_sections {
                let compiled = runtime
                    .render(instance, view, &cx)
                    .unwrap()
                    .compile(cx.viewport)
                    .unwrap();
                compiled.validate_parity().unwrap();
                for node in &compiled.semantics {
                    if node.key.as_str().starts_with("about/") {
                        assert!(
                            node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                            "{} is clipped at {viewport_width}x568: {:?}",
                            node.key.as_str(),
                            node.rect
                        );
                        about_keys.insert(node.key.as_str().to_string());
                    }
                }
                if section + 1 < about_sections {
                    let next = compiled
                        .hits
                        .iter()
                        .find(|hit| hit.key.as_str() == "about/pagination/next")
                        .expect("About exposes a semantic Next action")
                        .action
                        .clone();
                    runtime
                        .dispatch(
                            instance,
                            view,
                            AppEvent::Action(ActionInvocation {
                                id: next,
                                value: None,
                            }),
                        )
                        .unwrap();
                }
            }
            for key in [
                "about/copy-build-info",
                "about/open-site",
                "about/provenance",
                "about/provenance/row/version",
                "about/provenance/row/build",
                "about/provenance/row/commit",
                "about/provenance/row/built",
                "about/provenance/row/arch",
                "about/provenance/row/compiler",
                "about/provenance/row/signature",
                "about/support",
            ] {
                assert!(
                    about_keys.contains(key),
                    "missing {key} at {viewport_width}x568"
                );
            }

            let update = update_status(true);
            let update_state = UpdateState::from_status(1, "0.1.0", Some(&update), false);
            let (mut runtime, instance, view) = setup_with_update(update_state);
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(SettingsRoute::SoftwareUpdate),
                        value: None,
                    }),
                )
                .unwrap();
            let mut update_keys = BTreeSet::new();
            let update_sections = pager_total(
                &compile_settings_view(&runtime, instance, view, &cx),
                "updates/range",
            );
            for section in 0..update_sections {
                let compiled = runtime
                    .render(instance, view, &cx)
                    .unwrap()
                    .compile(cx.viewport)
                    .unwrap();
                compiled.validate_parity().unwrap();
                for node in &compiled.semantics {
                    // The Update route also hosts one shared config control
                    // (`settings/control/update.auto_apply`), so the audit
                    // follows that namespace too rather than missing the
                    // automatic-updates switch entirely.
                    if node.key.as_str().starts_with("updates/")
                        || node.key.as_str().starts_with("settings/control/update.")
                    {
                        assert!(
                            node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                            "{} is clipped at {viewport_width}x568: {:?}",
                            node.key.as_str(),
                            node.rect
                        );
                        update_keys.insert(node.key.as_str().to_string());
                    }
                }
                if section + 1 < update_sections {
                    let next = compiled
                        .hits
                        .iter()
                        .find(|hit| hit.key.as_str() == "updates/pagination/next")
                        .expect("Updates exposes a semantic Next action")
                        .action
                        .clone();
                    runtime
                        .dispatch(
                            instance,
                            view,
                            AppEvent::Action(ActionInvocation {
                                id: next,
                                value: None,
                            }),
                        )
                        .unwrap();
                }
            }
            for key in [
                "updates/install-now",
                "updates/headline",
                "updates/current",
                "updates/automatic",
                "settings/control/update.auto_apply",
                "updates/release-notes",
                "updates/outcome",
            ] {
                assert!(
                    update_keys.contains(key),
                    "missing {key} at {viewport_width}x568"
                );
            }
        }
    }

    #[test]
    fn short_landscape_audit_reaches_every_compact_slice_with_feedback() {
        const CHILD: &str = "ATERM_SETTINGS_LANDSCAPE_AUDIT_CHILD";
        const SCALE: &str = "ATERM_SETTINGS_LANDSCAPE_AUDIT_SCALE";
        const EXACT: &str = "native_settings::tests::short_landscape_audit_reaches_every_compact_slice_with_feedback";
        if std::env::var_os(CHILD).is_none() {
            for scale in ["1.0", "1.5", "2.0"] {
                let status = std::process::Command::new(std::env::current_exe().unwrap())
                    .args(["--exact", EXACT, "--nocapture"])
                    .env(CHILD, "1")
                    .env(SCALE, scale)
                    .env("RUST_TEST_THREADS", "1")
                    .status()
                    .expect("launch isolated short-landscape audit");
                assert!(status.success(), "short-landscape audit failed at {scale}×");
            }
            return;
        }

        let scale = std::env::var(SCALE).unwrap().parse::<f32>().unwrap();
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..crate::native_appearance::current_preferences()
            },
        );
        let cx = view_cx_at(568.0, 320.0);

        for feedback_present in [false, true] {
            let feedback = feedback_present.then(|| "Settings status changed".to_string());
            let variant = if feedback_present {
                "with feedback"
            } else {
                "without feedback"
            };

            // The compact category sheet exposes every destination as one
            // complete row beside an always-accessible pager.
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.compact_navigation = true;
                state.feedback = feedback.clone();
            }
            for (page, route) in SettingsRoute::ALL.into_iter().enumerate() {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!("categories {page} at {scale}× {variant}");
                assert_short_landscape_geometry(&compiled, scale, &context);
                assert!(
                    compiled
                        .semantic(&UiKey::new(format!("settings/categories{}", route.path())))
                        .is_some(),
                    "{context}: missing {}",
                    route.label()
                );
                assert_accessible_pager(
                    &compiled,
                    "settings/categories/pagination",
                    page,
                    SettingsRoute::ALL.len(),
                    &context,
                );
            }

            // Every native advanced category pages its preview and each real
            // control independently. This covers categories that the older
            // four-route visual matrix omitted.
            for route in [
                SettingsRoute::Appearance,
                SettingsRoute::TextFonts,
                SettingsRoute::CursorMotion,
                SettingsRoute::WindowTabs,
                SettingsRoute::KeyboardInput,
                SettingsRoute::Terminal,
                SettingsRoute::Security,
            ] {
                let (mut runtime, instance, view) = setup();
                let (total, expected_controls) = {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.navigate(route);
                    state.feedback = feedback.clone();
                    let expected_controls = state
                        .legacy
                        .fields
                        .iter()
                        .filter(|field| settings_field_is_visible(field.key, false, false))
                        .filter(|field| {
                            route
                                .section()
                                .is_some_and(|section| prefs::section_of(field.key) == section)
                        })
                        .count();
                    (
                        expected_controls + usize::from(focused_preview_key(state).is_some()),
                        expected_controls,
                    )
                };
                assert!(total >= expected_controls && total > 0, "{route:?}");
                let mut seen_controls = BTreeSet::new();
                for page in 0..total {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.page_scroll = page;
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "{} slice {page}/{total} at {scale}× {variant}",
                        route.label()
                    );
                    assert_short_landscape_geometry(&compiled, scale, &context);
                    seen_controls.extend(
                        compiled
                            .semantics
                            .iter()
                            .filter(|node| node.key.as_str().starts_with("settings/control/"))
                            .map(|node| node.key.as_str().to_string()),
                    );
                    if total > 1 {
                        assert_accessible_pager(
                            &compiled,
                            "settings/results-window",
                            page,
                            total,
                            &context,
                        );
                    }
                }
                assert_eq!(
                    seen_controls.len(),
                    expected_controls,
                    "{} at {scale}× {variant}",
                    route.label()
                );
            }

            // Manual is a first-class native destination too; its only action
            // must remain whole even at 2× with the status band present.
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Manual);
                state.feedback = feedback.clone();
            }
            let manual = compile_settings_view(&runtime, instance, view, &cx);
            let context = format!("Manual at {scale}× {variant}");
            assert_short_landscape_geometry(&manual, scale, &context);
            assert!(
                manual
                    .semantic(&UiKey::new("settings/manual/open"))
                    .is_some(),
                "{context}"
            );

            // Top Settings: all six requested controls, and the three visual
            // choices retain their live previews on their normal pages.
            let top = [
                (prefs::EDIT_THEME, Some("settings/top/theme/preview")),
                (
                    prefs::EDIT_WINDOW_THEME,
                    Some("settings/top/system-appearance/preview"),
                ),
                (
                    prefs::EDIT_CURSOR_TRAIL_STYLE,
                    Some("settings/top/cursor-trail/preview"),
                ),
                (prefs::EDIT_TRAIL_SOUNDS, None),
                (SPARKLE_WORDS_KEY, None),
                (KEYWORD_KITTIES_KEY, None),
            ];
            let (mut runtime, instance, view) = setup();
            for (page, (key, preview)) in top.into_iter().enumerate() {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Home);
                state.feedback = feedback.clone();
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!("Top Settings {key} at {scale}× {variant}");
                assert_short_landscape_geometry(&compiled, scale, &context);
                assert!(
                    compiled
                        .semantic(&UiKey::new(format!("settings/control/{key}")))
                        .is_some(),
                    "{context}: control"
                );
                if let Some(preview) = preview {
                    assert!(
                        compiled.semantic(&UiKey::new(preview)).is_some(),
                        "{context}"
                    );
                }
                assert_accessible_pager(
                    &compiled,
                    "settings/top/pagination",
                    page,
                    TOP_SETTING_SECTIONS,
                    &context,
                );
            }

            // Theme, macOS appearance, and trail browsing each keep every
            // picker page, option, Done, and (when needed) Prev/Next reachable.
            for key in [
                prefs::EDIT_THEME,
                prefs::EDIT_WINDOW_THEME,
                prefs::EDIT_CURSOR_TRAIL_STYLE,
            ] {
                let (mut runtime, instance, view) = setup();
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new(format!("settings/set/{key}")),
                            value: None,
                        }),
                    )
                    .unwrap();
                let (pages, page_size, option_count) = {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.feedback = feedback.clone();
                    configure_choice_picker_for_width(state, SettingsWidth::Compact);
                    let picker = state.choice_picker.as_ref().unwrap();
                    (
                        picker.options.len().div_ceil(picker.page_size.get()),
                        picker.page_size.get(),
                        picker.options.len(),
                    )
                };
                let mut seen_options = BTreeSet::new();
                for page in 0..pages {
                    {
                        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view)
                        else {
                            unreachable!();
                        };
                        let picker = state.choice_picker.as_mut().unwrap();
                        picker.offset.set(page * page_size);
                        state.common.last_focus = Some(UiKey::new(format!(
                            "settings/choice/{key}/{}",
                            picker.offset.get()
                        )));
                    }
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!("{key} picker {page}/{pages} at {scale}× {variant}");
                    assert_short_landscape_geometry(&compiled, scale, &context);
                    assert!(
                        compiled
                            .semantic(&UiKey::new("settings/top/choice-preview"))
                            .is_some(),
                        "{context}: live preview"
                    );
                    assert!(
                        compiled
                            .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
                            .is_some(),
                        "{context}: picker surface"
                    );
                    assert!(
                        compiled
                            .semantic(&UiKey::new("settings/choice-close"))
                            .is_some(),
                        "{context}: Done"
                    );
                    seen_options.extend(
                        compiled
                            .semantics
                            .iter()
                            .filter(|node| {
                                node.key
                                    .as_str()
                                    .starts_with(&format!("settings/choice/{key}/"))
                            })
                            .map(|node| node.key.as_str().to_string()),
                    );
                    if pages > 1 {
                        let previous = compiled
                            .semantic(&UiKey::new("settings/choice-page-prev"))
                            .unwrap();
                        let next = compiled
                            .semantic(&UiKey::new("settings/choice-page-next"))
                            .unwrap();
                        assert_eq!(previous.state.unwrap().enabled, page > 0, "{context}");
                        assert_eq!(next.state.unwrap().enabled, page + 1 < pages, "{context}");
                    }
                }
                assert_eq!(
                    seen_options.len(),
                    option_count,
                    "{key} at {scale}× {variant}"
                );
            }

            // Modified includes both reset-safe known structures and unknown
            // forward-compatible keys. Every exact authored override receives
            // its own complete summary/action slice.
            let mut source = (0..7)
                .map(|index| format!("future_{index} = {index}\n"))
                .collect::<String>();
            source.push_str("[keybindings]\n\"cmd+t\" = \"new_tab\"\n");
            let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
            let (mut runtime, instance, view) = setup();
            let overrides = {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
                state.navigate(SettingsRoute::Modified);
                state.feedback = feedback.clone();
                authored_manual_overrides(state)
            };
            assert_eq!(
                settings_field_result_count(match runtime.view_state(view) {
                    Some(AppViewState::Settings(state)) => state,
                    _ => unreachable!(),
                }),
                overrides.len()
            );
            for (page, authored) in overrides.iter().enumerate() {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!("Modified {} at {scale}× {variant}", authored.key);
                assert_short_landscape_geometry(&compiled, scale, &context);
                assert!(
                    compiled
                        .semantic(&UiKey::new(format!(
                            "settings/modified/manual/label/{}",
                            key_fragment(&authored.key)
                        )))
                        .is_some(),
                    "{context}: label"
                );
                assert!(
                    compiled
                        .semantic(&UiKey::new("settings/modified/manual/open"))
                        .is_some(),
                    "{context}: Manual escape hatch"
                );
                if authored.reset_safe {
                    assert!(
                        compiled
                            .semantic(&UiKey::new(format!(
                                "settings/modified/manual/reset/{}",
                                key_fragment(&authored.key)
                            )))
                            .is_some(),
                        "{context}: exact Reset"
                    );
                }
                assert_accessible_pager(
                    &compiled,
                    "settings/results-window",
                    page,
                    overrides.len(),
                    &context,
                );
            }

            // About's page count changes with Dynamic Type, so read the actual
            // accessible range and then audit every one of those slices.
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::About);
                state.feedback = feedback.clone();
            }
            let first = compile_settings_view(&runtime, instance, view, &cx);
            let about_total = pager_total(&first, "about/range");
            let mut about_keys = BTreeSet::new();
            for page in 0..about_total {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!("About {page}/{about_total} at {scale}× {variant}");
                assert_short_landscape_geometry(&compiled, scale, &context);
                assert_accessible_pager(&compiled, "about/pagination", page, about_total, &context);
                about_keys.extend(
                    compiled
                        .semantics
                        .iter()
                        .filter(|node| node.key.as_str().starts_with("about/"))
                        .map(|node| node.key.as_str().to_string()),
                );
            }
            for key in [
                "about/copy-build-info",
                "about/open-site",
                "about/provenance/row/version",
                "about/provenance/row/build",
                "about/provenance/row/commit",
                "about/provenance/row/built",
                "about/provenance/row/arch",
                "about/provenance/row/compiler",
                "about/provenance/row/signature",
                "about/support",
            ] {
                assert!(
                    about_keys.contains(key),
                    "About missing {key} at {scale}× {variant}; saw {about_keys:?}"
                );
            }

            // Audit both updater shapes. Sections are the status summary, the
            // one action, the automatic-updates switch, the outcome, and every
            // bounded release-notes page — the same set either way, because the
            // notes panel always says something.
            for staged in [false, true] {
                let status = update_status(staged);
                let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
                let (mut runtime, instance, view) = setup_with_update(update_state);
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.navigate(SettingsRoute::SoftwareUpdate);
                    state.feedback = feedback.clone();
                }
                // The page count is what the live pager reports; the authored
                // `update_compact_sections` accounting must agree with it, which
                // is the anti-divergence property worth pinning here.
                let update_total = pager_total(
                    &compile_settings_view(&runtime, instance, view, &cx),
                    "updates/range",
                );
                let mut keys = BTreeSet::new();
                for page in 0..update_total {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.page_scroll = page;
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "Update staged={staged} {page}/{update_total} at {scale}× {variant}"
                    );
                    assert_short_landscape_geometry(&compiled, scale, &context);
                    assert_accessible_pager(
                        &compiled,
                        "updates/pagination",
                        page,
                        update_total,
                        &context,
                    );
                    keys.extend(
                        compiled
                            .semantics
                            .iter()
                            .filter(|node| node.key.as_str().starts_with("updates/"))
                            .map(|node| node.key.as_str().to_string()),
                    );
                }
                for key in [
                    "updates/hero",
                    "updates/install-now",
                    "updates/automatic",
                    "updates/release-notes",
                ] {
                    assert!(
                        keys.contains(key),
                        "Update missing {key}: {staged} {scale}× {variant}"
                    );
                }
                // The retired multi-button, service-card and explainer surfaces
                // must not come back at any width or Dynamic Type step.
                for key in [
                    "updates/check",
                    "updates/install-relaunch",
                    "updates/install-when-safe",
                    "updates/service/service/value",
                    "updates/service/running/value",
                    "updates/service/staged/value",
                    "updates/detail-card",
                    "updates/process",
                ] {
                    assert!(
                        !keys.contains(key),
                        "retired Update surface {key} reappeared: {staged} {scale}× {variant}"
                    );
                }
            }

            // Packages uses the same stable atomic-page contract for status,
            // both actions, all three maintenance switches, and every bounded program.
            let packages_state = live_packages_state(None);
            let packages_total = packages_compact_sections(&packages_state.projection());
            let (mut runtime, instance, view) = setup();
            assert!(runtime.replace_settings_packages(packages_state, 2));
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Packages);
                state.feedback = feedback;
            }
            let mut package_keys = BTreeSet::new();
            for page in 0..packages_total {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!("Packages {page}/{packages_total} at {scale}× {variant}");
                assert_short_landscape_geometry(&compiled, scale, &context);
                assert_accessible_pager(
                    &compiled,
                    "packages/pagination",
                    page,
                    packages_total,
                    &context,
                );
                package_keys.extend(
                    compiled
                        .semantics
                        .iter()
                        .filter(|node| {
                            node.key.as_str().starts_with("packages/")
                                || node.key.as_str().starts_with("settings/control/packages.")
                        })
                        .map(|node| node.key.as_str().to_string()),
                );
            }
            for key in [
                "packages/hero",
                "packages/check",
                "packages/install-default",
                "packages/service-line",
                "settings/control/packages.auto_update",
                "settings/control/packages.auto_install",
                "packages/consent-note",
                "packages/programs/ay",
            ] {
                assert!(
                    package_keys.contains(key),
                    "Packages missing {key} at {scale}× {variant}"
                );
            }
        }
    }

    #[test]
    fn numeric_slider_preserves_cursor_trail_default_and_both_endpoints() {
        let state = SettingsViewState::new(&Config::default());
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_MS)
            .expect("cursor trail duration field");
        let range = prefs::range_of(field.key).expect("bounded slider range");
        assert_eq!(range.step, 10.0);
        assert_eq!(
            numeric_slider_value(field),
            Some((260.0, "260".to_string()))
        );
        for expected in [30.0, 260.0, 2000.0] {
            assert_eq!(
                normalize_slider_value(expected, range),
                Some(expected.to_string())
            );
        }
        let row = setting_row(&state, 0, field, false, false, SettingsWidth::Compact);
        let compiled = UiTree::new(row)
            .compile(LogicalRect::new(0.0, 0.0, 320.0, 72.0))
            .unwrap();
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!(
                    "settings/control/{}",
                    prefs::EDIT_CURSOR_TRAIL_MS
                )))
                .expect("semantic slider")
                .value,
            SemanticValue::Number {
                value: 260.0,
                minimum: 30.0,
                maximum: 2000.0,
            }
        );
    }

    #[test]
    fn unset_text_setting_semantics_report_the_effective_default_while_paint_stays_quiet() {
        let state = SettingsViewState::new(&Config::default());
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_FONT_FAMILY)
            .expect("font family field");
        assert!(field.seed.is_none());
        assert!(!field.placeholder.is_empty());
        let row = setting_row(&state, 0, field, false, false, SettingsWidth::Compact);
        let compiled = UiTree::new(row)
            .compile(LogicalRect::new(0.0, 0.0, 390.0, 72.0))
            .unwrap();
        let key = UiKey::new(format!("settings/control/{}", field.key));
        assert_eq!(
            compiled.semantic(&key).expect("semantic text field").value,
            SemanticValue::Text(field.placeholder.clone())
        );
        let paint = compiled
            .paint
            .iter()
            .find(|node| node.key == key)
            .expect("paint text field");
        let UiContent::TextField(control) = &paint.content else {
            panic!("font family is a text field")
        };
        assert_eq!(control.spec.visual_value.as_deref(), Some(""));
    }

    #[test]
    fn update_check_command_and_reducer_share_enabled_state() {
        let assert_state = |update: UpdateState, expected_enabled: bool| {
            let (mut runtime, instance, view) = setup_with_update(update);
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(SettingsRoute::SoftwareUpdate),
                        value: None,
                    }),
                )
                .unwrap();
            let command = runtime
                .commands(instance, view)
                .unwrap()
                .into_iter()
                .find(|command| command.id.as_str() == "updates/check")
                .expect("update command");
            assert_eq!(command.enabled, expected_enabled);
            let outcome = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new("updates/check"),
                        value: None,
                    }),
                )
                .unwrap();
            assert_eq!(
                outcome
                    .effects
                    .iter()
                    .filter(|effect| matches!(effect, AppEffect::Update { .. }))
                    .count(),
                usize::from(expected_enabled)
            );
        };

        assert_state(UpdateState::from_status(1, "0.1.0", None, false), false);
        let enabled = update_status(false);
        assert_state(
            UpdateState::from_status(1, "0.1.0", Some(&enabled), false),
            true,
        );
        assert_state(
            UpdateState::from_status(1, "0.1.0", Some(&enabled), true),
            false,
        );
    }

    #[test]
    fn virtual_window_exports_semantic_pagination_controls() {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Appearance),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx();
        let first = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        assert!(
            first
                .semantic(&UiKey::new("settings/results-range"))
                .is_some()
        );
        let previous = first
            .semantic(&UiKey::new("settings/results-window/previous"))
            .expect("Previous remains in the accessibility tree while disabled");
        assert!(!previous.state.unwrap().enabled);
        let next = first
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == "settings/results-window/next")
            .expect("Next is visible and actionable")
            .action
            .clone();
        assert_eq!(next.as_str(), "settings/page-down");

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: next,
                    value: None,
                }),
            )
            .unwrap();
        let second = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        assert!(
            second
                .hits
                .iter()
                .any(|hit| hit.key.as_str() == "settings/results-window/previous"),
            "after paging, Previous is enabled through the same semantic path"
        );
        assert!(
            second
                .semantic(&UiKey::new("settings/results-range"))
                .unwrap()
                .label
                .starts_with("2–")
        );
    }

    #[test]
    fn compact_field_pager_reaches_every_control_at_phone_height() {
        let (mut runtime, instance, view) = setup();
        let expected = {
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                panic!("Settings view");
            };
            settings_field_result_count(state)
        };
        let cx = view_cx_at(320.0, 568.0);
        let mut seen = BTreeSet::new();
        for _ in 0..expected {
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            compiled.validate_parity().unwrap();
            for node in compiled
                .semantics
                .iter()
                .filter(|node| node.key.as_str().starts_with("settings/control/"))
            {
                assert!(
                    node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                    "{} is complete at 320×568: {:?}",
                    node.key.as_str(),
                    node.rect
                );
                seen.insert(node.key.as_str().to_string());
            }
            let Some(next) = compiled
                .hits
                .iter()
                .find(|hit| hit.key.as_str() == "settings/results-window/next")
                .map(|hit| hit.action.clone())
            else {
                break;
            };
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: next,
                        value: None,
                    }),
                )
                .unwrap();
        }
        assert_eq!(
            seen.len(),
            expected,
            "semantic Next reaches every omitted Appearance control"
        );
    }

    #[test]
    fn search_is_global_ranked_and_keeps_category_context() {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/search"),
                    value: Some(SemanticInput::Text("clipboard".to_string())),
                }),
            )
            .unwrap();
        let cx = view_cx();
        let first = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        // "clipboard" lands two LIVE native switches on one page, each under
        // its own category heading — allow_osc52_query joined the ordinary
        // security policies when the GUI's clipboard callback learned to
        // answer authorized queries, so the Manual-handoff row this search
        // used to produce for it (and the results-window paging that
        // followed) no longer exists for this term.
        assert!(
            first
                .semantic(&UiKey::new("settings/control/allow_osc52_query"))
                .is_some(),
            "the OSC 52 read policy is a live, searchable native switch"
        );
        assert!(
            first
                .semantic(&UiKey::new(
                    "settings/group-heading/security---permissions/allow-osc52-query"
                ))
                .is_some(),
            "…grouped under its Security · Permissions heading"
        );
        let compiled = first;
        assert!(
            compiled
                .semantic(&UiKey::new("settings/control/copy_on_select"))
                .is_some()
        );
        let label = compiled
            .semantic(&UiKey::new("settings/label/copy_on_select"))
            .expect("globally matched input setting");
        assert!(
            label.label.contains("Input"),
            "category context: {}",
            label.label
        );
        assert!(
            compiled
                .semantics
                .iter()
                .filter(|node| node.key.as_str().starts_with("settings/nav/"))
                .all(|node| node.state.is_none_or(|state| !state.selected)),
            "global search must not imply that results are route-scoped"
        );
    }

    #[test]
    fn default_on_boolean_apply_and_reset_round_trip_through_real_config_service() {
        let (mut runtime, instance, view) = setup();
        let mut service = VersionedConfigService::new(String::new()).unwrap();

        let modified = {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                panic!("Settings view");
            };
            state.navigate(SettingsRoute::Modified);
            runtime
                .render(instance, view, &view_cx())
                .unwrap()
                .compile(view_cx().viewport)
                .unwrap()
        };
        assert_eq!(
            modified
                .semantic(&UiKey::new("settings/empty"))
                .unwrap()
                .label,
            "No modified settings.",
            "resolved default-on Boolean seeds are not raw overrides"
        );

        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                    value: Some(SemanticInput::Bool(false)),
                }),
            )
            .unwrap();
        let (patch, operation) = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, reply } => Some((patch.clone(), reply.operation)),
                _ => None,
            })
            .expect("Boolean edit reaches config service");
        assert_eq!(
            patch.edits[0].expected,
            ExpectedConfigValue::Exact(None),
            "the absent raw key, not effective true, is the OCC expectation"
        );
        let (snapshot, undo) = apply_real_config_patch(&mut service, &patch);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ConfigPatchFinished {
                    operation,
                    outcome: ConfigPatchOutcome::Applied {
                        revision: snapshot.revision,
                        undo,
                    },
                },
            )
            .unwrap();
        runtime
            .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        let blink = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
            .unwrap();
        assert_eq!(SettingsState::display_value(blink), "false");
        assert!(state.is_explicit(prefs::EDIT_CURSOR_BLINK));

        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/reset/{}", prefs::EDIT_CURSOR_BLINK)),
                    value: None,
                }),
            )
            .unwrap();
        let (patch, operation) = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, reply } => Some((patch.clone(), reply.operation)),
                _ => None,
            })
            .expect("reset reaches config service");
        assert_eq!(
            patch.edits[0].expected,
            ExpectedConfigValue::Exact(Some("false".to_string()))
        );
        assert_eq!(patch.edits[0].value, None);
        let (snapshot, undo) = apply_real_config_patch(&mut service, &patch);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ConfigPatchFinished {
                    operation,
                    outcome: ConfigPatchOutcome::Applied {
                        revision: snapshot.revision,
                        undo,
                    },
                },
            )
            .unwrap();
        runtime
            .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        let blink = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
            .unwrap();
        assert_eq!(
            SettingsState::display_value(blink),
            "true",
            "removing the key restores the effective default-on display"
        );
        assert!(!state.is_explicit(prefs::EDIT_CURSOR_BLINK));
    }

    #[test]
    fn indeterminate_config_publication_stays_unverified_until_snapshot_reconciliation() {
        let (mut runtime, instance, view) = setup();
        let (before_raw, before_display) = {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                panic!("Settings view");
            };
            state.last_undo = Some(41);
            let field = state
                .legacy
                .fields
                .iter()
                .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
                .unwrap();
            (
                state.raw_value(prefs::EDIT_CURSOR_BLINK),
                SettingsState::display_value(field).to_string(),
            )
        };
        let requested = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                    value: Some(SemanticInput::Bool(false)),
                }),
            )
            .unwrap();
        let (patch, operation) = requested
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, reply } => Some((patch.clone(), reply.operation)),
                _ => None,
            })
            .expect("change enters the config writer");

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ConfigPatchFinished {
                    operation,
                    outcome: ConfigPatchOutcome::Indeterminate {
                        message: "directory sync could not be verified".to_string(),
                    },
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        assert_eq!(state.raw_value(prefs::EDIT_CURSOR_BLINK), before_raw);
        assert_eq!(
            SettingsState::display_value(
                state
                    .legacy
                    .fields
                    .iter()
                    .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
                    .unwrap()
            ),
            before_display,
            "an unverified publication is never projected as a committed value"
        );
        assert_eq!(state.unverified_patch.as_ref(), Some(&patch));
        assert!(state.config_reconciliation_required);
        assert!(state.last_undo.is_none());
        let feedback = state.feedback.as_deref().unwrap();
        assert!(
            feedback.starts_with("Publication unverified:"),
            "{feedback}"
        );
        assert!(feedback.contains("Reload aterm.toml"), "{feedback}");
        assert!(!feedback.contains("Applied") && !feedback.contains("Saved"));

        let commands = runtime.commands(instance, view).unwrap();
        for id in ["settings/undo", "settings/reset-all"] {
            assert!(
                !commands
                    .iter()
                    .find(|command| command.id.as_str() == id)
                    .unwrap()
                    .enabled,
                "{id} remains blocked until reconciliation"
            );
        }
        let blocked = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_COPY_ON_SELECT)),
                    value: Some(SemanticInput::Bool(true)),
                }),
            )
            .unwrap();
        assert!(
            blocked
                .effects
                .iter()
                .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
            "no blind follow-up write is issued"
        );

        let snapshot = VersionedConfigService::new(String::new())
            .unwrap()
            .snapshot();
        runtime
            .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        assert!(!state.config_reconciliation_required);
        assert!(state.unverified_patch.is_none());
        assert!(state.feedback.is_none());
    }

    #[test]
    fn reset_all_requires_an_explicit_confirmation_and_discloses_its_scope() {
        let (mut runtime, instance, view) = setup();
        let expected_edits = match runtime.view_state(view) {
            Some(AppViewState::Settings(state)) => state
                .legacy
                .fields
                .iter()
                .filter(|field| !prefs::manual_only_key(field.key))
                .filter(|field| state.raw_values.contains_key(field.key))
                .count(),
            _ => panic!("Settings view"),
        };

        let ask = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all"),
                    value: None,
                }),
            )
            .unwrap();
        assert!(
            ask.effects
                .iter()
                .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
            "the disclosure step must never mutate configuration"
        );

        let cx = view_cx_at(1_080.0, 720.0);
        let confirmation = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let status = confirmation
            .semantic(&UiKey::new("settings/status"))
            .expect("scope disclosure");
        assert_eq!(
            status.label,
            "Reset all scalar preferences? Lists and maps stay. Custom records stay. Unknown keys stay."
        );
        for (key, preserved) in [
            ("settings/status/visual", "Reset all scalars?"),
            ("settings/status/collections", "Lists and maps stay."),
            ("settings/status/records", "Custom records stay."),
            ("settings/status/unknown", "Unknown keys stay."),
        ] {
            assert!(
                confirmation.semantic(&UiKey::new(key)).is_none(),
                "{key} is visual copy, not another live region"
            );
            assert!(confirmation.paint.iter().any(|node| {
                node.key == UiKey::new(key)
                    && matches!(&node.content, UiContent::Text(spec) if spec.text == preserved)
            }));
        }
        assert_eq!(
            confirmation
                .semantics
                .iter()
                .filter(|node| {
                    node.key.as_str().starts_with("settings/status")
                        && node.role == SemanticRole::Status
                })
                .count(),
            1
        );
        assert!(
            confirmation
                .semantic(&UiKey::new("settings/reset-all-cancel"))
                .is_some()
        );
        assert!(
            confirmation
                .semantic(&UiKey::new("settings/reset-all-confirm"))
                .is_some()
        );

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all-cancel"),
                    value: None,
                }),
            )
            .unwrap();
        let stale_confirm = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all-confirm"),
                    value: None,
                }),
            )
            .unwrap();
        assert!(
            stale_confirm
                .effects
                .iter()
                .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
            "a stale semantic confirm cannot bypass the disclosure"
        );

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all"),
                    value: None,
                }),
            )
            .unwrap();
        let confirmed = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all-confirm"),
                    value: None,
                }),
            )
            .unwrap();
        let patch = confirmed
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .expect("explicit confirmation emits one clearing patch");
        assert_eq!(patch.edits.len(), expected_edits);
        assert!(patch.edits.iter().all(|edit| edit.value.is_none()));
        assert!(
            patch
                .edits
                .iter()
                .all(|edit| !prefs::manual_only_key(&edit.key)),
            "Reset All preserves every Manual-only value"
        );
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        assert!(!state.reset_all_confirmation);
    }

    #[test]
    fn config_snapshot_refreshes_every_view_after_external_or_cross_view_change() {
        let (mut runtime, instance, first) = setup();
        let mut core_views = ViewStore::default();
        let _ = core_views.insert_native(instance).unwrap();
        let second = core_views.insert_native(instance).unwrap();
        runtime
            .attach_view(
                second,
                instance,
                AppViewState::Settings(Box::new(SettingsViewState::new(&Config::default()))),
            )
            .unwrap();

        let mut service = VersionedConfigService::new(String::new()).unwrap();
        let snapshot = service
            .replace_external("cursor_blink = false\nfont_px = 19.0\n".to_string())
            .unwrap();
        for view in [first, second] {
            runtime
                .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                panic!("Settings view");
            };
            let display = |key| {
                SettingsState::display_value(
                    state
                        .legacy
                        .fields
                        .iter()
                        .find(|field| field.key == key)
                        .unwrap(),
                )
                .to_string()
            };
            assert_eq!(display(prefs::EDIT_CURSOR_BLINK), "false");
            assert_eq!(display(prefs::EDIT_FONT_PX), "19");
            assert!(state.is_explicit(prefs::EDIT_CURSOR_BLINK));
            assert!(state.is_explicit(prefs::EDIT_FONT_PX));
        }
    }

